import{_ as e,o as t,c as r,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Namakarana source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/17-namakarana-profile.md","filePath":"reference/17-namakarana-profile.md","lastUpdated":1788614098000}'),o={name:"reference/17-namakarana-profile.md"};function d(i,a,s,c,h,l){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="namakarana-source-profile" tabindex="-1">Namakarana source profile <a class="header-anchor" href="#namakarana-source-profile" aria-label="Permalink to &quot;Namakarana source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The configured naming-ceremony profile is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter VIII, “Post-natal ceremonies” / “Naming the child (Namakarana),” internal printed page 22 (physical PDF page 25) in the inspected 2020 Chistabo derivative:</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">inspected 2020 Chistabo derivative</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture. The source describes an election for the ceremony; it does not replace family, sampradaya or priestly rules for choosing the name itself.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Prefer the 10th, 12th or 16th day after birth; otherwise elect an auspicious day</td><td><code>manual_checks</code></td><td>The finder has no birth-date input, so it discloses rather than fabricates this check.</td></tr><tr><td>Sixteen named Nakshatras are auspicious</td><td><code>allowed_nakshatras</code></td><td>Any other active slot-time Nakshatra rejects the candidate.</td></tr><tr><td>Reject Tithis 4, 6, 8, 9, 12, 14, Purnima and Amavasya</td><td><code>avoid_tithi_numbers</code></td><td>The engine numbers Tithis 1–15 within each Paksha, so both Purnima and Amavasya map to terminal number 15.</td></tr><tr><td>Monday, Wednesday, Thursday and Friday are good; other weekdays are not</td><td><code>allowed_varas</code></td><td>An unlisted weekday rejects the entire day with an explicit reason.</td></tr><tr><td>Fixed Lagnas are preferable; common Lagnas are good with benefic occupancy</td><td><code>prefer_lagna_class</code>; <code>manual_checks</code></td><td>Fixed Lagna receives the existing disclosed preference; the exceptional chart condition remains manual.</td></tr><tr><td>Strengthen Lagna, leave the 8th vacant, and consider the stated Guru/malefic/Shukra/Chandra placements</td><td><code>manual_checks</code></td><td>Full election-chart occupancy, dignity and aspect judgment is not claimed by the finder.</td></tr><tr><td>The name should suit the ruling Nakshatra</td><td><code>manual_checks</code></td><td>Naming guidance is visible but not generated automatically.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>The existing samskara filters, hard avoid windows, Shubh-Choghadiya and Tithi-family ranking preferences, personal scoring and relative tiers are shared project rules. This Chapter VIII locator does not establish them. MCP returns the stable <code>muhurta.namakarana</code> claim and repeats every manual check; the browser consumes the same generated activity contract.</p>',9)])])}const p=e(o,[["render",d]]);export{u as __pageData,p as default};
